body.script:
(function () {
  var svg = document.documentElement;
  var viewport = document.getElementById("synnical-viewport");
  var frame = document.getElementById("synnical-os-frame");
  var blocked = document.getElementById("blocked");
  var loaded = false;

  function fitViewport() {
    var vv = window.visualViewport;
    var width = Math.max(1, Math.round(vv ? vv.width : window.innerWidth));
    var height = Math.max(1, Math.round(vv ? vv.height : window.innerHeight));
    svg.setAttribute("width", String(width));
    svg.setAttribute("height", String(height));
    svg.style.width = width + "px";
    svg.style.height = height + "px";
    viewport.setAttribute("width", String(width));
    viewport.setAttribute("height", String(height));
  }

  fitViewport();
  window.addEventListener("resize", fitViewport, { passive: true });
  if (window.visualViewport) {
    window.visualViewport.addEventListener("resize", fitViewport, { passive: true });
  }

  frame.addEventListener("load", function () {
    loaded = true;
    blocked.style.display = "none";
    fitViewport();
  });

  setTimeout(function () {
    if (!loaded) blocked.style.display = "grid";
  }, 4000);
})();
